const raw = $json.text;

if (typeof raw !== 'string' || !raw.trim()) {
  throw new Error('Gemini returned no text to parse.');
}

const cleaned = raw
  .trim()
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/\s*```$/, '');

let result;

try {
  result = JSON.parse(cleaned);
} catch (error) {
  throw new Error(
    'Gemini response was not valid JSON: ' + error.message
  );
}

if (
  typeof result.tailored_resume !== 'string' ||
  !result.review_report ||
  !Array.isArray(result.review_report.changes_made) ||
  !Array.isArray(result.review_report.skills_to_confirm) ||
  !Array.isArray(result.review_report.other_recommendations)
) {
  throw new Error(
    'Gemini response is missing required resume or review-report fields.'
  );
}

return { json: result };
